-- ads-spy — schema Supabase (Postgres).
-- Applique ce fichier en entier pour creer les tables + le seed de demo.
-- Acces 100% server-side via la cle (anon/publishable) -> RLS activee + policy permissive.

create table if not exists shops (
  id bigint generated by default as identity primary key,
  name text not null,
  created_at timestamptz not null default now()
);

create table if not exists competitors (
  id bigint generated by default as identity primary key,
  shop_id bigint not null references shops(id) on delete cascade,
  name text not null,
  facebook_page_id text not null,
  active boolean not null default true,
  note text
);

create table if not exists ads (
  id bigint generated by default as identity primary key,
  shop_id bigint not null references shops(id) on delete cascade,
  competitor text not null,
  ad_id text not null,
  ad_url text not null,
  spend_estime_eur double precision not null,
  spend_jour_eur double precision not null,
  prev_spend_jour_eur double precision,
  jours_diffusion integer not null,
  reach bigint,
  suivi boolean not null default false,
  first_seen text,
  updated_at timestamptz not null default now(),
  unique (shop_id, ad_id)
);

create index if not exists ads_shop_idx on ads (shop_id);
create index if not exists competitors_shop_idx on competitors (shop_id);

-- RLS : outil interne, acces via la cle server-side. Policy permissive (l'ecriture
-- publique reste protegee au niveau de l'API par ADS_SPY_TOKEN).
alter table shops enable row level security;
alter table competitors enable row level security;
alter table ads enable row level security;
do $$ begin
  create policy "all_shops" on shops for all using (true) with check (true);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy "all_competitors" on competitors for all using (true) with check (true);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy "all_ads" on ads for all using (true) with check (true);
exception when duplicate_object then null; end $$;

-- Seed boutique Marco Moretti (boutique de Hugo) + 3 concurrents + ~56 pubs demo.
select setval(pg_get_serial_sequence('shops','id'), (select max(id) from shops));
select setval(pg_get_serial_sequence('competitors','id'), (select max(id) from competitors));
select setval(pg_get_serial_sequence('ads','id'), (select max(id) from ads));
